<?php
require_once __DIR__ . '/config/auth.php';
if ($table = table_id_from_qr()) $_SESSION['selected_table_id'] = $table;
$pageTitle='Menu'; $cat=(int)($_GET['kategori']??0); $q=trim((string)($_GET['q']??''));
$categories=dbq('SELECT id,nama FROM categories ORDER BY urutan,nama')->fetchAll();
$sql='SELECT m.*, c.nama AS kategori FROM menus m JOIN categories c ON c.id=m.category_id WHERE 1=1'; $args=[];
if($cat){$sql.=' AND m.category_id=?';$args[]=$cat;}
if($q!==''){$sql.=' AND (m.nama LIKE ? OR m.deskripsi LIKE ?)';$args[]='%'.$q.'%';$args[]='%'.$q.'%';}
$sql.=' ORDER BY m.is_best_seller DESC, m.created_at DESC';$st=$pdo->prepare($sql);$st->execute($args);$menus=$st->fetchAll();
require __DIR__ . '/includes/header.php'; ?>
<section class="max-w-7xl mx-auto px-4 pt-10 pb-6"><p class="section-kicker">dibuat untuk mood kamu</p><h1 class="font-serif text-4xl sm:text-5xl mt-2">menu Kopiah</h1><p class="text-sm text-coffee/65 mt-3 max-w-xl">dari kopi klasik sampai camilan manis, pilih teman untuk momenmu hari ini.</p>
<form method="get" class="mt-7 flex flex-col sm:flex-row gap-3"><input class="field flex-1" type="search" name="q" value="<?= h($q) ?>" placeholder="cari kopi, matcha, camilan..."><select class="field sm:max-w-xs" name="kategori" aria-label="Filter kategori"><option value="0">Semua kategori</option><?php foreach($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= $cat===(int)$c['id']?'selected':'' ?>><?= h($c['nama']) ?></option><?php endforeach; ?></select><button class="btn btn-coffee" type="submit">Cari menu</button></form>
<div class="flex gap-2 overflow-x-auto py-5"> <a href="<?= h(BASE_URL) ?>/menu.php" class="px-4 py-2 rounded-full text-sm whitespace-nowrap <?= !$cat?'bg-coffee text-white':'bg-white/80' ?>">Semua</a><?php foreach($categories as $c): ?><a href="?kategori=<?= (int)$c['id'] ?><?= $q!==''?'&q='.urlencode($q):'' ?>" class="px-4 py-2 rounded-full text-sm whitespace-nowrap <?= $cat===(int)$c['id']?'bg-coffee text-white':'bg-white/80' ?>"><?= h($c['nama']) ?></a><?php endforeach; ?></div></section>
<section class="max-w-7xl mx-auto px-4 pb-12"><div class="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 sm:gap-6"><?php foreach($menus as $m): ?><article class="card menu-card flex flex-col"><a href="<?= h(BASE_URL) ?>/menu-detail.php?id=<?= (int)$m['id'] ?>" class="overflow-hidden relative"><img class="menu-photo" src="<?= h($m['foto'] ?: 'assets/img/coffee-placeholder.svg') ?>" alt="<?= h($m['nama']) ?>" loading="lazy"><?php if(!$m['is_available']||(int)$m['stok']<=0): ?><span class="absolute top-3 left-3 bg-black/75 text-white text-xs rounded-full px-3 py-1">Habis</span><?php elseif($m['is_best_seller']): ?><span class="absolute top-3 left-3 badge-soft">Best Seller</span><?php elseif(strtotime($m['created_at'])>=strtotime('-7 days')): ?><span class="absolute top-3 left-3 badge-soft badge-caramel">Baru</span><?php endif; ?></a><div class="p-4 flex flex-col flex-1"><span class="text-xs text-coffee/55"><?= h($m['kategori']) ?></span><a href="<?= h(BASE_URL) ?>/menu-detail.php?id=<?= (int)$m['id'] ?>" class="font-semibold leading-snug mt-1"><?= h($m['nama']) ?></a><p class="text-xs leading-5 text-coffee/60 mt-2 line-clamp-2"><?= h($m['deskripsi']) ?></p><div class="mt-auto pt-4 flex items-center justify-between gap-2"><b class="text-sm"><?= money($m['harga']) ?></b><?php if($m['is_available'] && (int)$m['stok']>0): ?><a class="rounded-full bg-coffee text-white w-9 h-9 flex items-center justify-center" href="<?= h(BASE_URL) ?>/menu-detail.php?id=<?= (int)$m['id'] ?>">+</a><?php else: ?><span class="text-xs text-red-700">tidak tersedia</span><?php endif; ?></div></div></article><?php endforeach; ?></div><?php if(!$menus): ?><div class="text-center py-20"><p class="font-serif text-2xl">menu belum ditemukan</p><p class="text-sm text-coffee/60 mt-2">coba kata kunci atau kategori lain, ya.</p><a class="btn btn-coffee mt-5" href="<?= h(BASE_URL) ?>/menu.php">Reset filter</a></div><?php endif; ?></section>
<?php require __DIR__ . '/includes/footer.php'; ?>
